1665→// hasAnyChanges is a lightweight alternative to hasCodeChanges that compares
1666→// tree hashes without doing a full diff. Returns true if the commit's tree
1667→// differs from its parent's tree. This may include metadata-only changes,
1668→// but is O(1) instead of O(files) — suitable for list views.
1669→func hasAnyChanges(commit *object.Commit) bool {
1670→	if commit.NumParents() == 0 {
1671→		return true
1672→	}
1673→	parent, err := commit.Parent(0)
1674→	if err != nil {
1675→		return true
1676→	}
1677→	return commit.TreeHash != parent.TreeHash
1678→}
