 934→func getBranchCheckpoints(ctx context.Context, repo *git.Repository, limit int) ([]strategy.RewindPoint, error) {
 935→	store := checkpoint.NewGitStore(repo)
 936→
 937→	// Get all committed checkpoints for lookup
 938→	committedInfos, err := store.ListCommitted(ctx)
 939→	if err != nil {
 940→		committedInfos = nil // Continue without committed checkpoints
 941→	}
 942→
 943→	// Build map of checkpoint ID -> committed info
 944→	committedByID := make(map[id.CheckpointID]checkpoint.CommittedInfo)
 945→	for _, info := range committedInfos {
 946→		if !info.CheckpointID.IsEmpty() {
 947→			committedByID[info.CheckpointID] = info
 948→		}
 949→	}
 950→
 951→	head, err := repo.Head()
 952→	if err != nil {
 953→		// Unborn HEAD (no commits yet) - return empty list instead of erroring
 954→		if errors.Is(err, plumbing.ErrReferenceNotFound) {
 955→			return []strategy.RewindPoint{}, nil
 956→		}
 957→		return nil, fmt.Errorf("failed to get HEAD: %w", err)
 958→	}
 959→
 960→	// Check if we're on the default branch (needed for getReachableTemporaryCheckpoints)
 961→	isOnDefault, _ := strategy.IsOnDefaultBranch(repo)
 962→
 963→	// Fetch metadata branch tree once for reading session prompts (cheap tree lookups).
 964→	// This avoids calling ReadLatestSessionContent per checkpoint which reads+parses
 965→	// the full JSONL transcript — extremely slow with hundreds of checkpoints.
 966→	metadataTree, _ := strategy.GetMetadataBranchTree(repo) //nolint:errcheck // Best-effort, continue without prompts
 967→
 968→	var points []strategy.RewindPoint
 969→
 970→	collectCheckpoint := func(c *object.Commit) {
 971→		cpID, found := trailers.ParseCheckpoint(c.Message)
 972→		if !found {
 973→			return
 974→		}
 975→		cpInfo, found := committedByID[cpID]
 976→		if !found {
 977→			return
 978→		}
 979→
 980→		message := strings.Split(c.Message, "\n")[0]
 981→		point := strategy.RewindPoint{
 982→			ID:               c.Hash.String(),
 983→			Message:          message,
 984→			Date:             c.Committer.When,
 985→			IsLogsOnly:       true, // Committed checkpoints are logs-only
 986→			CheckpointID:     cpID,
 987→			SessionID:        cpInfo.SessionID,
 988→			IsTaskCheckpoint: cpInfo.IsTask,
 989→			ToolUseID:        cpInfo.ToolUseID,
 990→			Agent:            cpInfo.Agent,
 991→		}
 992→		// Read session prompt from metadata branch tree (best-effort).
 993→		// Read prompt.txt directly from the latest session subdirectory instead of
 994→		// parsing the full transcript — prompt.txt is tiny vs multi-MB transcripts.
 995→		if metadataTree != nil {
 996→			point.SessionPrompt = readPromptFromMetadataTree(metadataTree, cpID, cpInfo.SessionCount)
 997→		}
 998→
 999→		points = append(points, point)
1000→	}
1001→
1002→	if isOnDefault {
1003→		// On the default branch, use full DAG walk to find checkpoint commits
1004→		// on merged feature branches (second parents of merge commits).
1005→		iter, iterErr := repo.Log(&git.LogOptions{
1006→			From:  head.Hash(),
1007→			Order: git.LogOrderCommitterTime,
1008→		})
