1016→			if err := ctx.Err(); err != nil {
1017→				return err //nolint:wrapcheck // Propagating context cancellation
1018→			}
1019→			if count >= commitScanLimit {
1020→				return storer.ErrStop
1021→			}
1022→			count++
1023→			collectCheckpoint(c)
1024→			return nil
1025→		})
1026→	} else {
1027→		// On feature branches, use first-parent walk with branch filtering.
1028→		// This avoids walking into main's full history through merge commit parents.
1029→		reachableFromMain := computeReachableFromMain(ctx, repo)
1030→
1031→		err = walkFirstParentCommits(ctx, repo, head.Hash(), commitScanLimit, func(c *object.Commit) error {
1032→			// Once we hit a commit reachable from main on the first-parent chain,
1033→			// all earlier ancestors are also shared-with-main, so stop scanning.
1034→			if reachableFromMain[c.Hash] {
1035→				return errStopIteration
1036→			}
1037→			collectCheckpoint(c)
1038→			return nil
1039→		})
1040→	}
1041→
1042→	if err != nil {
1043→		return nil, fmt.Errorf("error iterating commits: %w", err)
1044→	}
1045→
1046→	// Get temporary checkpoints from ALL shadow branches whose base commit is reachable from HEAD.
1047→	tempPoints := getReachableTemporaryCheckpoints(ctx, repo, store, head.Hash(), isOnDefault, limit)
1048→	points = append(points, tempPoints...)
