445→// ExtractFirstPrompt extracts and truncates the first meaningful prompt from prompt content.
446→// Prompts are separated by "\n\n---\n\n". Skips empty prompts and separator-only content.
447→// Returns empty string if no valid prompt is found.
448→func ExtractFirstPrompt(content string) string {
449→	if content == "" {
450→		return ""
451→	}
452→
453→	// Prompts are separated by "\n\n---\n\n"
454→	// Find the first non-empty prompt
455→	prompts := strings.Split(content, "\n\n---\n\n")
456→	var firstPrompt string
457→	for _, p := range prompts {
458→		cleaned := strings.TrimSpace(p)
459→		// Skip empty prompts or prompts that are just dashes/separators
460→		if cleaned == "" || isOnlySeparators(cleaned) {
461→			continue
462→		}
463→		firstPrompt = cleaned
464→		break
465→	}
466→
467→	if firstPrompt == "" {
468→		return ""
469→	}
470→
471→	return TruncateDescription(firstPrompt, MaxDescriptionLength)
472→}
