491→// ReadAgentTypeFromTree reads the agent type from a checkpoint's metadata.json file in a git tree.
492→// If metadata.json doesn't exist (shadow branches), it falls back to detecting the agent
493→// from the presence of agent-specific config files (.gemini/settings.json or .claude/).
494→// Returns agent.AgentTypeUnknown if the agent type cannot be determined.
495→func ReadAgentTypeFromTree(tree *object.Tree, checkpointPath string) types.AgentType {
496→	// First, try to read from metadata.json (present in condensed/committed checkpoints)
497→	metadataPath := checkpointPath + "/" + paths.MetadataFileName
498→	if file, err := tree.File(metadataPath); err == nil {
499→		if content, err := file.Contents(); err == nil {
500→			var metadata checkpoint.CommittedMetadata
501→			if err := json.Unmarshal([]byte(content), &metadata); err == nil && metadata.Agent != "" {
502→				return metadata.Agent
503→			}
504→		}
505→	}
506→
507→	// Fall back to detecting agent from config files (shadow branches don't have metadata.json).
508→	// Order: Gemini (most specific check), Claude (established default), OpenCode (newest/preview).
509→	if _, err := tree.File(".gemini/settings.json"); err == nil {
510→		return agent.AgentTypeGemini
511→	}
512→	if _, err := tree.Tree(".claude"); err == nil {
513→		return agent.AgentTypeClaudeCode
514→	}
515→	// OpenCode: .opencode directory or opencode.json config
516→	if _, err := tree.Tree(".opencode"); err == nil {
517→		return agent.AgentTypeOpenCode
518→	}
519→	if _, err := tree.File("opencode.json"); err == nil {
520→		return agent.AgentTypeOpenCode
521→	}
522→
523→	return agent.AgentTypeUnknown
524→}
