526→// isOnlySeparators checks if a string contains only dashes, spaces, and newlines.
527→func isOnlySeparators(s string) bool {
528→	for _, r := range s {
529→		if r != '-' && r != ' ' && r != '\n' && r != '\r' && r != '\t' {
530→			return false
531→		}
532→	}
533→	return true
534→}
