536→// ReadAllSessionPromptsFromTree reads the first prompt for all sessions in a multi-session checkpoint.
537→// Returns a slice of prompts parallel to sessionIDs (oldest to newest).
538→// For single-session checkpoints, returns a slice with just the root prompt.
539→func ReadAllSessionPromptsFromTree(tree *object.Tree, checkpointPath string, sessionCount int, sessionIDs []string) []string {
540→	if sessionCount <= 1 || len(sessionIDs) <= 1 {
541→		// Single session - just return the root prompt
542→		prompt := ReadSessionPromptFromTree(tree, checkpointPath)
543→		if prompt != "" {
544→			return []string{prompt}
545→		}
546→		return nil
547→	}
548→
549→	// Multi-session: read prompts from archived folders (0/, 1/, etc.) and root
550→	prompts := make([]string, len(sessionIDs))
551→
552→	// Read archived session prompts (folders 0, 1, ... N-2)
553→	for i := range sessionCount - 1 {
554→		archivedPath := fmt.Sprintf("%s/%d", checkpointPath, i)
555→		prompts[i] = ReadSessionPromptFromTree(tree, archivedPath)
556→	}
557→
558→	// Read the most recent session prompt (at root level)
559→	prompts[len(prompts)-1] = ReadSessionPromptFromTree(tree, checkpointPath)
560→
561→	return prompts
562→}
