790→func (s *GitStore) ReadSessionContent(ctx context.Context, checkpointID id.CheckpointID, sessionIndex int) (*SessionContent, error) {
791→	if err := ctx.Err(); err != nil {
792→		return nil, err //nolint:wrapcheck // Propagating context cancellation
793→	}
794→
795→	tree, err := s.getSessionsBranchTree()
796→	if err != nil {
797→		return nil, ErrCheckpointNotFound
798→	}
799→
800→	checkpointPath := checkpointID.Path()
801→	checkpointTree, err := tree.Tree(checkpointPath)
802→	if err != nil {
803→		return nil, ErrCheckpointNotFound
804→	}
805→
806→	// Get the session subdirectory
807→	sessionDir := strconv.Itoa(sessionIndex)
808→	sessionTree, err := checkpointTree.Tree(sessionDir)
809→	if err != nil {
810→		return nil, fmt.Errorf("session %d not found: %w", sessionIndex, err)
811→	}
812→
813→	result := &SessionContent{}
814→
815→	// Read session-specific metadata
816→	var agentType types.AgentType
817→	if metadataFile, fileErr := sessionTree.File(paths.MetadataFileName); fileErr == nil {
818→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
819→			if jsonErr := json.Unmarshal([]byte(content), &result.Metadata); jsonErr == nil {
820→				agentType = result.Metadata.Agent
821→			}
822→		}
823→	}
824→
825→	// Read transcript
826→	if transcript, transcriptErr := readTranscriptFromTree(ctx, sessionTree, agentType); transcriptErr == nil && transcript != nil {
827→		result.Transcript = transcript
828→	}
829→
830→	// Read prompts
831→	if file, fileErr := sessionTree.File(paths.PromptFileName); fileErr == nil {
832→		if content, contentErr := file.Contents(); contentErr == nil {
833→			result.Prompts = content
834→		}
835→	}
836→
837→	// Read context
838→	if file, fileErr := sessionTree.File(paths.ContextFileName); fileErr == nil {
839→		if content, contentErr := file.Contents(); contentErr == nil {
840→			result.Context = content
841→		}
842→	}
843→
844→	return result, nil
845→}
