332→// writeSessionToSubdirectory writes a single session's files to a numbered subdirectory.
333→// Returns the absolute file paths from the git tree root for the sessions map.
334→func (s *GitStore) writeSessionToSubdirectory(ctx context.Context, opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
335→	filePaths := SessionFilePaths{}
336→
337→	// Clear any existing entries at this path so stale files from a previous
338→	// write (e.g. prompt.txt, context.md) don't persist on overwrite.
339→	for key := range entries {
340→		if strings.HasPrefix(key, sessionPath) {
341→			delete(entries, key)
342→		}
343→	}
344→
345→	// Write transcript
346→	if err := s.writeTranscript(ctx, opts, sessionPath, entries); err != nil {
347→		return filePaths, err
